export interface ChoiceSpec {
  value: string;
  caption: string;
  idleGlyph?: string;
  activeGlyph?: string;
  color?: string;
  disabled?: boolean;
}

export interface ChoiceView extends ChoiceSpec {
  readonly selected: boolean;
}

export class ChoiceModel {
  public readonly groupKey: string;
  public readonly direction: "ltr" | "rtl";
  private readonly choices: ChoiceSpec[];
  private selected: string | undefined;

  constructor(
    groupKey: string,
    choices: readonly ChoiceSpec[],
    initialValue?: string,
    direction: "ltr" | "rtl" = "ltr",
  ) {
    if (typeof groupKey !== "string" || !Array.isArray(choices)) {
      throw new RangeError("Invalid input");
    }

    const normalizedGroupKey = groupKey.trim();
    if (
      normalizedGroupKey.length === 0 ||
      (direction !== "ltr" && direction !== "rtl")
    ) {
      throw new RangeError("Invalid group metadata");
    }

    this.groupKey = normalizedGroupKey;
    this.direction = direction;

    const seen = new Set<string>();
    this.choices = choices.map((choice) => {
      if (
        choice === null ||
        typeof choice !== "object" ||
        typeof choice.value !== "string" ||
        typeof choice.caption !== "string"
      ) {
        throw new RangeError("Invalid choice");
      }

      const value = choice.value.trim();
      const caption = choice.caption.trim();
      if (value.length === 0 || caption.length === 0 || seen.has(value)) {
        throw new RangeError("Invalid choice");
      }

      seen.add(value);
      return {
        value,
        caption,
        idleGlyph: choice.idleGlyph,
        activeGlyph: choice.activeGlyph,
        color: choice.color,
        disabled: choice.disabled,
      };
    });

    if (initialValue !== undefined && typeof initialValue === "string") {
      const candidate = initialValue.trim();
      const match = this.choices.find(
        (choice) => choice.value === candidate && !choice.disabled,
      );
      this.selected = match?.value;
    }
  }

  select(value: string): boolean {
    if (typeof value !== "string") return false;

    const normalized = value.trim();
    if (normalized.length === 0) return false;

    const match = this.choices.find(
      (choice) => choice.value === normalized,
    );
    if (match === undefined) return false;

    this.selected = match.value;
    return true;
  }

  selectedValue(): string | undefined {
    return this.selected;
  }

  view(): ChoiceView[] {
    return this.choices.map((choice) => ({
      ...choice,
      selected: choice.value === this.selected,
    }));
  }
}

