import { ChoiceModel, ChoiceSpec, ChoiceView } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(action: () => void, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

rangeError(() => new ChoiceModel(' ', []), 'blank group key');
rangeError(() => new ChoiceModel('g', [{ value: '', caption: 'x' }]), 'blank value');
rangeError(() => new ChoiceModel('g', [{ value: 'x', caption: ' ' }]), 'blank caption');
rangeError(() => new ChoiceModel('g', [{ value: ' x ', caption: 'one' }, { value: 'x', caption: 'two' }]), 'normalized duplicate');
rangeError(() => new ChoiceModel('g', [], undefined, 'vertical' as 'ltr'), 'malformed direction');

const empty = new ChoiceModel(' empty ', []);
equal(empty.groupKey, 'empty', 'group key is trimmed');
equal(empty.direction, 'ltr', 'default direction is ltr');
equal(empty.selectedValue(), undefined, 'empty model has no selection');
equal(empty.view().length, 0, 'empty view is valid');

const source: ChoiceSpec[] = [
  { value: ' one ', caption: ' First ', idleGlyph: 'i', activeGlyph: 'a', color: '#123', disabled: false },
  { value: 'two', caption: ' Second ', disabled: true },
  { value: 'three', caption: 'Third' },
];
const model = new ChoiceModel(' group ', source, ' one ', 'rtl');
equal(model.groupKey, 'group', 'normalized group key exposed');
equal(model.direction, 'rtl', 'explicit direction exposed');
equal(model.selectedValue(), 'one', 'enabled initial value selected');
let view = model.view();
equal(view.length, 3, 'view preserves all choices');
equal(view[0].value, 'one', 'choice value is trimmed');
equal(view[0].caption, 'First', 'caption is trimmed');
equal(view[0].selected, true, 'initial choice marked selected');
equal(view[1].selected, false, 'only one choice selected');

source[0].value = 'changed';
source[0].caption = 'changed';
source.push({ value: 'four', caption: 'Fourth' });
equal(model.view().length, 3, 'constructor array is copied');
equal(model.view()[0].value, 'one', 'constructor objects are copied');

const oldSelection = model.selectedValue();
equal(model.select(' two '), false, 'disabled choice cannot be selected');
equal(model.select('unknown'), false, 'unknown choice cannot be selected');
equal(model.select('   '), false, 'blank choice cannot be selected');
equal(model.selectedValue(), oldSelection, 'failed selection preserves current value');
equal(model.select(' three '), true, 'enabled normalized choice can be selected');
equal(model.selectedValue(), 'three', 'selection changes');
view = model.view();
equal(view[0].selected, false, 'old choice is deselected');
equal(view[2].selected, true, 'new choice is selected');

const anotherView = model.view();
assert(view !== anotherView, 'view arrays are fresh');
assert(view[0] !== anotherView[0], 'view objects are fresh');
(view[2] as { value: string; selected: boolean }).value = 'tampered';
(view[2] as { value: string; selected: boolean }).selected = false;
view.length = 0;
equal(model.selectedValue(), 'three', 'returned view mutation cannot change selection');
equal(model.view()[2].value, 'three', 'returned choice mutation is isolated');
equal(model.view().length, 3, 'returned array mutation is isolated');

const disabledInitial = new ChoiceModel('g', [{ value: 'x', caption: 'X', disabled: true }], 'x');
equal(disabledInitial.selectedValue(), undefined, 'disabled initial choice is ignored');
const unknownInitial = new ChoiceModel('g', [{ value: 'x', caption: 'X' }], 'missing');
equal(unknownInitial.selectedValue(), undefined, 'unknown initial choice is ignored');

